class ProviderConfig(BaseSettings):
    model_config = SettingsConfigDict(env_prefix='OW_', extra='ignore')
    api_key: SecretStr
    base_url: str = 'https://api.openrouter.ai'
    model: str = 'openrouter/inclusionai/ling-3.0-flash:free'

class ProviderRouter:
    def __init__(self, config: ProviderConfig):
        self._config = config  # validated, immutable
        self._clients: dict[str, Any] = {}
    def invalidate(self, name: str | None = None):
        if name is None: self._clients.clear()
        else: self._clients.pop(name, None)
    def get_client(self, model: str) -> Any:
        key = model.split(':')[0] if ':' in model else 'openai'
        if key not in self._clients:
            self._clients[key] = self._build(key)  # lazy build from validated config
        return self._clients[key]

# Injection via deps_type
ctx = RuntimeCtx(provider_config=ProviderConfig())
agent = Agent(model, deps_type=RuntimeCtx)
sess = ctx.get_session()  # typed, no env guessing
